property.value:
let $repeats := ('ForeachStatement', 'ForStatement', 'WhileStatement', 'DoStatement'),
    $iterating := ('forEach', 'forEachOrdered', 'map', 'flatMap', 'filter', 'anyMatch', 'allMatch', 'noneMatch',
                   'peek', 'mapToObj', 'mapToInt', 'mapToLong', 'mapToDouble'),
    $cacheType := function($call) {
      matches($call/ClassType/@SimpleName, '(Cache|Caches|Memo|Memoizer|Shared)$')
    },
    $units := function($node) {
      let $method := $node/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration][1]
      return $node/ancestor::*[local-name() = $repeats
        or self::LambdaExpression[parent::ArgumentList/parent::MethodCall[@MethodName = $iterating]]]
        [exists(ancestor::* intersect $method)]
    },
    $varying := function($units) {
      ($units//VariableId
        | $units//AssignmentExpression/*[1][self::VariableAccess]
        | $units//UnaryExpression[@Operator = ('++', '--')]/VariableAccess)/@Name
    }
return
//LocalVariableDeclaration/VariableDeclarator[ConstructorCall]
  [let $call := ConstructorCall,
       $name := VariableId/@Name,
       $units := $units(.),
       $uses := ancestor::Block[1]//VariableAccess[@Name = $name]
   return exists($units)
     and $cacheType($call) and $call/ArgumentList/@Size > 0
     and empty($call/ArgumentList//(MethodCall | ConstructorCall))
     and empty($call/ArgumentList//VariableAccess[@Name = $varying($units[last()])])
     and (every $use in $uses satisfies exists($use/parent::*[self::MethodCall or self::FieldAccess][*[1] is $use]))]
  /ConstructorCall
